static int is_whitespace_token(const char *tok) {
    if (!tok || tok[0] == '\0') return 0;
    for (size_t i = 0; tok[i] != '\0'; i++) {
        if (!(tok[i] == ' ' || tok[i] == '\t' || tok[i] == '\r' || tok[i] == '\n')) return 0;
    }
    return 1;
}

int insert_word_in_sentence(FileContent *fc, int sent_idx, int word_idx, const char *word) {
    if (sent_idx < 0 || sent_idx > fc->sentence_count) {
        log_formatted(LOG_ERROR, "Invalid sentence index: %d (file has %d sentences)", 
                     sent_idx, fc->sentence_count);
        return -1;
    }

    if (sent_idx == fc->sentence_count) {
        if (fc->sentence_count >= fc->capacity) {
            int newcap = fc->capacity ? fc->capacity * 2 : 10;
            while (newcap <= fc->sentence_count) newcap *= 2;
            Sentence *tmp = realloc(fc->sentences, sizeof(Sentence) * newcap);
            if (!tmp) {
                log_formatted(LOG_ERROR, "Out of memory expanding sentences");
                return -1;
            }
            fc->sentences = tmp;
            fc->capacity = newcap;
        }
        fc->sentences[fc->sentence_count].capacity = 10;
        fc->sentences[fc->sentence_count].word_count = 0;
        fc->sentences[fc->sentence_count].words = malloc(sizeof(char*) * fc->sentences[fc->sentence_count].capacity);
        if (!fc->sentences[fc->sentence_count].words) {
            log_formatted(LOG_ERROR, "Out of memory allocating words for new sentence");
            return -1;
        }
        if (!(fc->sentence_count == 1 && fc->sentences[0].word_count == 0))
            fc->sentence_count++;
    }

    Sentence *sent = &fc->sentences[sent_idx];

    // Compute logical word count (exclude pure-whitespace tokens)
    int logical_count = 0;
    for (int i = 0; i < sent->word_count; i++) {
        if (!is_whitespace_token(sent->words[i])) logical_count++;
    }

    if (word_idx < 1 || word_idx > logical_count + 1) {
        log_formatted(LOG_ERROR, "Invalid word index: %d (sentence has %d logical words, valid range: 1-%d)", 
                     word_idx, logical_count, logical_count + 1);
        return -1;
    }

    // Convert user-facing word_idx to actual array index in sent->words
    // We insert BEFORE the logical word at position word_idx (1-based), or at end if word_idx == logical_count+1
    int actual_idx = 0;
    if (word_idx == 1) {
        // insert at beginning => actual_idx = 0
        actual_idx = 0;
    } else {
        int seen = 0;
        actual_idx = sent->word_count; // default to end
        for (int i = 0; i < sent->word_count; i++) {
            if (!is_whitespace_token(sent->words[i])) {
                seen++;
                if (seen == word_idx - 1) {
                    // insert after this token -> actual index is i+1
                    actual_idx = i + 1;
                    break;
                }
            }
        }
    }

    // Split input into parts (now can include whitespace tokens)
    int part_count;
    char **parts = split_by_delimiters(word, &part_count);
    if (part_count == 0) {
        free(parts);
        log_formatted(LOG_WARNING, "Empty word, skipping insertion");
        return 0;
    }

    // Count how many delimiters (new sentences) we're creating
    int new_sentences = 0;
    int last_delimiter_idx = -1;
    for (int i = 0; i < part_count; i++) {
        if (is_delimiter(parts[i][0]) && parts[i][1] == '\0') {
            last_delimiter_idx = i;
        }
    }
    if (last_delimiter_idx >= 0 && last_delimiter_idx < part_count - 1) {
        new_sentences = 1;
    }
    for (int i = 0; i < part_count; i++) {
        if (is_delimiter(parts[i][0]) && parts[i][1] == '\0') new_sentences++;
    }

    log_formatted(LOG_DEBUG, "Inserting %d parts, %d will create new sentences", part_count, new_sentences);

    // Make room for new sentences if needed
    if (new_sentences > 0) {
        int new_total = fc->sentence_count + new_sentences;
        if (new_total > fc->capacity) {
            while (fc->capacity < new_total) fc->capacity *= 2;
            fc->sentences = realloc(fc->sentences, sizeof(Sentence) * fc->capacity);
        }
        for (int i = fc->sentence_count - 1; i > sent_idx; i--) {
            fc->sentences[i + new_sentences] = fc->sentences[i];
        }
        for (int i = 1; i <= new_sentences; i++) {
            fc->sentences[sent_idx + i].capacity = 10;
            fc->sentences[sent_idx + i].word_count = 0;
            fc->sentences[sent_idx + i].words = malloc(sizeof(char*) * 10);
        }
    }

    // Insert parts at actual_idx; we must shift the existing array accordingly
    Sentence *cur_sent = &fc->sentences[sent_idx];
    int cur_actual_idx = actual_idx;
    int in_new_sentence = 0;

    for (int pi = 0; pi < part_count; pi++) {
        // If we are in the original sentence and need to insert at position cur_actual_idx,
        // shift existing entries to make space
        if (!in_new_sentence) {
            if (cur_sent->word_count + 1 >= cur_sent->capacity) {
                cur_sent->capacity = cur_sent->capacity ? cur_sent->capacity * 2 : 10;
                cur_sent->words = realloc(cur_sent->words, sizeof(char*) * cur_sent->capacity);
            }
            for (int k = cur_sent->word_count; k > cur_actual_idx; k--) {
                cur_sent->words[k] = cur_sent->words[k - 1];
            }
            cur_sent->words[cur_actual_idx] = strdup(parts[pi]);
            cur_sent->word_count++;
            cur_actual_idx++;
            // If this part is a delimiter that causes a sentence split and more content follows, move remaining to next sentence
            int should_split = (pi == last_delimiter_idx && last_delimiter_idx < part_count - 1);
            if (should_split) {
                Sentence *next_sent = &fc->sentences[sent_idx + 1];
                int words_to_move = cur_sent->word_count - cur_actual_idx;
                for (int j = 0; j < words_to_move; j++) {
                    if (next_sent->word_count >= next_sent->capacity) {
                        next_sent->capacity *= 2;
                        next_sent->words = realloc(next_sent->words, sizeof(char*) * next_sent->capacity);
                    }
                    next_sent->words[next_sent->word_count++] = cur_sent->words[cur_actual_idx + j];
                }
                cur_sent->word_count = cur_actual_idx;
                cur_sent = next_sent;
                cur_actual_idx = cur_sent->word_count;
                in_new_sentence = 1;
            }
        } else {
            // append into new sentence
            if (cur_sent->word_count >= cur_sent->capacity) {
                cur_sent->capacity *= 2;
                cur_sent->words = realloc(cur_sent->words, sizeof(char*) * cur_sent->capacity);
            }
            cur_sent->words[cur_sent->word_count++] = strdup(parts[pi]);
            cur_actual_idx = cur_sent->word_count;
        }
        free(parts[pi]);
    }
    free(parts);

    fc->sentence_count += new_sentences;
    log_formatted(LOG_DEBUG, "After insertion, file has %d sentences", fc->sentence_count);
    return new_sentences;
}
