char** split_by_delimiters(const char *word, int *count) {
    int cap = 10;
    char **parts = malloc(sizeof(char*) * cap);
    *count = 0;

    char buffer[MAX_WORD];
    int buf_idx = 0;

    for (int i = 0; word[i] != '\0'; i++) {
        char ch = word[i];
        if (ch == '\n') {
            /* Save current buffer if not empty (preserve whitespace exactly) */
            if (buf_idx > 0) {
                buffer[buf_idx] = '\0';
                parts[*count] = strdup(buffer);
                (*count)++;
                buf_idx = 0;
                if (*count >= cap) {
                    cap *= 2;
                    parts = realloc(parts, sizeof(char*) * cap);
                }
            }

            /* Save newline as separate token */
            parts[*count] = strdup("\n");
            (*count)++;
            if (*count >= cap) {
                cap *= 2;
                parts = realloc(parts, sizeof(char*) * cap);
            }
        } else if (is_delimiter(ch)) {
            /* Save pending buffer */
            if (buf_idx > 0) {
                buffer[buf_idx] = '\0';
                parts[*count] = strdup(buffer);
                (*count)++;
                buf_idx = 0;
                if (*count >= cap) {
                    cap *= 2;
                    parts = realloc(parts, sizeof(char*) * cap);
                }
            }
            /* Save delimiter as token */
            buffer[0] = ch;
            buffer[1] = '\0';
            parts[*count] = strdup(buffer);
            (*count)++;
            if (*count >= cap) {
                cap *= 2;
                parts = realloc(parts, sizeof(char*) * cap);
            }
        } else if (ch == ' ' || ch == '\t' || ch == '\r') {
            /* Save any pending non-space buffer first */
            if (buf_idx > 0 && !(buffer[0]==' ' || buffer[0]=='\t' || buffer[0]=='\r')) {
                buffer[buf_idx] = '\0';
                parts[*count] = strdup(buffer);
                (*count)++;
                buf_idx = 0;
                if (*count >= cap) {
                    cap *= 2;
                    parts = realloc(parts, sizeof(char*) * cap);
                }
            }
            /* Capture the full whitespace run as a token */
            int widx = 0;
            char wbuf[MAX_WORD];
            while (word[i] != '\0' && (word[i] == ' ' || word[i] == '\t' || word[i] == '\r')) {
                if (widx < MAX_WORD - 1) wbuf[widx++] = word[i];
                i++;
            }
            i--; // stepped one too far
            wbuf[widx] = '\0';
            parts[*count] = strdup(wbuf);
            (*count)++;
            if (*count >= cap) {
                cap *= 2;
                parts = realloc(parts, sizeof(char*) * cap);
            }
        } else {
            buffer[buf_idx++] = ch;
            if (buf_idx >= MAX_WORD - 1) {
                buffer[buf_idx] = '\0';
                parts[*count] = strdup(buffer);
                (*count)++;
                buf_idx = 0;
                if (*count >= cap) {
                    cap *= 2;
                    parts = realloc(parts, sizeof(char*) * cap);
                }
            }
        }
    }

    // Save remaining buffer
    if (buf_idx > 0) {
        buffer[buf_idx] = '\0';
        parts[*count] = strdup(buffer);
        (*count)++;
    }

    return parts;
}
