char** split_by_delimiters(const char *word, int *count) {
    int cap = 10;
    char **parts = malloc(sizeof(char*) * cap);
    *count = 0;

    char buffer[MAX_WORD];
    int buf_idx = 0;

    for (int i = 0; word[i] != '\0'; i++) {
