            buffer[buf_idx++] = ch;
            if (buf_idx >= MAX_WORD - 1) {
                buffer[buf_idx] = '\0';
                parts[*count] = strdup(buffer);
                (*count)++;
                buf_idx = 0;
                if (*count >= cap) {
                    cap *= 2;
                    parts = realloc(parts, sizeof(char*) * cap);
                }
            }
        }
    }

    // Save remaining buffer
    if (buf_idx > 0) {
        buffer[buf_idx] = '\0';
        parts[*count] = strdup(buffer);
        (*count)++;
    }

