+    int logical_count = 0;
+    for (int i = 0; i < sent->word_count; i++) {
+        if (!is_whitespace_token(sent->words[i])) logical_count++;
+    }
+
+    if (word_idx < 1 || word_idx > logical_count + 1) {
+        log_formatted(LOG_ERROR, "Invalid word index: %d (sentence has %d logical words, valid range: 1-%d)",
+                      word_idx, logical_count, logical_count + 1);
+        return -1;
+    }
+
+    /* Map user-facing 1-based word_idx to the actual array index in sent->words.
+       We insert AFTER the (word_idx-1)-th logical token. If word_idx==1 we insert at beginning (index 0). */
+    int actual_idx = 0;
+    if (word_idx == 1) {
+        actual_idx = 0;
+    } else {
+        int seen = 0;
+        actual_idx = sent->word_count; /* default append position */
+        for (int i = 0; i < sent->word_count; i++) {
+            if (!is_whitespace_token(sent->words[i])) {
+                seen++;
+                if (seen == word_idx - 1) {
+                    actual_idx = i + 1;
+                    break;
+                }
+            }
+        }
+    }
