+    int part_count;
+    char **parts = split_by_delimiters(word, &part_count);
+    if (part_count == 0) {
+        free(parts);
+        log_formatted(LOG_WARNING, "Empty word, skipping insertion");
+        return 0;
+    }
+
+    /* Determine how many new sentences will be created by delimiters */
+    int new_sentences = 0;
+    int last_delim_idx = -1;
