+                int words_to_move = cur_sent->word_count - cur_idx;
+                for (int j = 0; j < words_to_move; j++) {
+                    if (next_sent->word_count >= next_sent->capacity) {
+                        next_sent->capacity *= 2;
+                        next_sent->words = realloc(next_sent->words, sizeof(char*) * next_sent->capacity);
+                    }
+                    next_sent->words[next_sent->word_count++] = cur_sent->words[cur_idx + j];
+                }
+                cur_sent->word_count = cur_idx;
+                cur_sent = next_sent;
+                cur_idx = cur_sent->word_count;
+                in_new_sentence = 1;
+            }
