+                cur_sent->capacity *= 2;
+                cur_sent->words = realloc(cur_sent->words, sizeof(char*) * cur_sent->capacity);
+            }
+            cur_sent->words[cur_sent->word_count++] = strdup(parts[pi]);
+            cur_idx = cur_sent->word_count;
+        }
